using Servicio.RetazoMarket.Business.DTOs.Proveedor;using Servicio.RetazoMarket.Business.Exceptions;using Servicio.RetazoMarket.Business.Interfaces;using Servicio.RetazoMarket.Business.Mappers;using Servicio.RetazoMarket.Business.Validators;using Servicio.RetazoMarket.DataManagment.Interfaces;using Servicio.RetazoMarket.DataManagment.Models;using Servicio.RetazoMarket.DataManagment.Models.Common;
namespace Servicio.RetazoMarket.Business.Services;
public class ProveedorService:IProveedorService { private readonly IProveedorDataService _data;public ProveedorService(IProveedorDataService data)=>_data=data;private static string Correo(string c)=>c.Trim().ToLowerInvariant();public async Task<IReadOnlyList<ProveedorResponse>> ObtenerTodosAsync(CancellationToken ct=default)=>(await _data.ObtenerTodosAsync(ct)).Select(ProveedorBusinessMapper.ToResponse).ToList();public async Task<ProveedorResponse?> ObtenerPorIdAsync(int id,CancellationToken ct=default){var m=await _data.ObtenerPorIdAsync(id,ct);return m is null?null:ProveedorBusinessMapper.ToResponse(m);}public async Task<ProveedorResponse?> ObtenerPorCorreoAsync(string correo,CancellationToken ct=default){var m=await _data.ObtenerPorCorreoAsync(Correo(correo),ct);return m is null?null:ProveedorBusinessMapper.ToResponse(m);}public async Task<DataPagedResult<ProveedorResponse>> BuscarAsync(ProveedorFiltroRequest f,CancellationToken ct=default){var e=ProveedorValidator.ValidarFiltro(f);if(e.Any())throw new ValidationException("Filtro inválido.",e);var r=await _data.BuscarAsync(new ProveedorFiltroDataModel{nombre=f.nombre?.Trim(),correo=f.correo is null?null:Correo(f.correo),estado=f.estado?.Trim().ToUpperInvariant(),id_material=f.id_material,PageNumber=f.page_number,PageSize=f.page_size},ct);return new(){Items=r.Items.Select(ProveedorBusinessMapper.ToResponse).ToList(),PageNumber=r.PageNumber,PageSize=r.PageSize,TotalRecords=r.TotalRecords};}public async Task<ProveedorResponse> CrearAsync(CrearProveedorRequest r,CancellationToken ct=default){var e=ProveedorValidator.Validar(r);if(e.Any())throw new ValidationException("Solicitud inválida.",e);if(await _data.ExistePorCorreoAsync(Correo(r.prov_correo),ct))throw new ValidationException("Ya existe un proveedor con ese correo.");return ProveedorBusinessMapper.ToResponse(await _data.CrearAsync(ProveedorBusinessMapper.ToDataModel(r),ct));}public async Task<ProveedorResponse?> ActualizarAsync(ActualizarProveedorRequest r,CancellationToken ct=default){var e=ProveedorValidator.Validar(r);if(e.Any())throw new ValidationException("Solicitud inválida.",e);var otro=await _data.ObtenerPorCorreoAsync(Correo(r.prov_correo),ct);if(otro is not null&&otro.id_proveedor!=r.id_proveedor)throw new ValidationException("Ya existe otro proveedor con ese correo.");var m=await _data.ActualizarAsync(ProveedorBusinessMapper.ToDataModel(r),ct);return m is null?null:ProveedorBusinessMapper.ToResponse(m);}public Task<bool> EliminarAsync(int id,CancellationToken ct=default)=>_data.EliminarLogicoAsync(id,ct);}
